dtsPropsFor.Chip:
children: React.ReactNode;
    onClick?: () => void;
    /** Present makes this a toggle and renders the pressed state. */
    pressed?: boolean;
    /** Computed-outlier hue, reserved for flag filters (DESIGN.md §2). */
    flag?: boolean;
    disabled?: boolean;
    title?: string;
    className?: string;

dtsPropsFor.CopyableText:
value: string;
    label?: string;
    className?: string;

dtsPropsFor.DetailSection:
sectionKey: string;
    meta?: React.ReactNode;
    meter?: React.ReactNode;
    children: React.ReactNode;
    className?: string;

dtsPropsFor.EmptyState:
icon?: React.ReactNode;
    title: React.ReactNode;
    body?: React.ReactNode;
    actions?: React.ReactNode;
    tone?: "ok" | "danger";

dtsPropsFor.ErrorState:
title?: string;
    message?: string;
    error?: unknown;
    actions?: React.ReactNode;
    onRetry?: () => void;

dtsPropsFor.FacetDrawer:
groups: FacetGroup[];
    onToggle: (facetId: string, value: string) => void;
    onClear: () => void;
    onClose: () => void;
    emptyText: string;

dtsPropsFor.IconButton:
children: React.ReactNode;
    label: string;
    onClick?: () => void;
    href?: string;
    download?: boolean;
    disabled?: boolean;
    className?: string;

dtsPropsFor.ListEmpty:
kind: "first-run" | "filtered" | "cleared";
    what: string;
    /** Active filters, for the diagnostic treatment. */
    filters?: Array<{
        label: string;
        clear: () => void;
    }>;
    onClearAll?: () => void;
    action?: {
        label: string;
        run: () => void;
    };

dtsPropsFor.ListGroup:
collapsed: boolean;
    onToggle: () => void;
    label: string;
    count: number;
    /** Everything in the header after the chevron — icon, title, controls. */
    head: React.ReactNode;
    children: React.ReactNode;
    className?: string;
    chevronSize?: number;

dtsPropsFor.Loading:
what?: string;
    label?: string;
    onRetry?: () => void;

dtsPropsFor.ModePill:
/** Mode ids that are lit. */
    modes: string[] | Set<string>;
    /** Present makes the pill interactive. */
    onToggle?: (id: string) => void;
    label?: string;

dtsPropsFor.NotFound:
what: string;
    id?: string;
    backTo?: string;
    backLabel?: string;

dtsPropsFor.Picker:
open: boolean;
    label: string;
    options: PickerOption[];
    current: string;
    onPick: (id: string) => void;
    onClose: () => void;

dtsPropsFor.SearchBar:
value: string;
    onInput: (v: string) => void;
    /** Placeholder and accessible name — the field has no visible label. */
    label: string;
    count?: number;
    className?: string;

dtsPropsFor.SearchDisclosure:
label: string;
    value: string;
    icon: Icon;
    options: DisclosureOption[];
    /** The clear-the-filter row, always first and always present. */
    allLabel: string;
    current: string;
    onPick: (id: string) => void;
    /** Shown when the search matches nothing. Name the right noun. */
    emptyText: string;

dtsPropsFor.Sheet:
label: string;
    onClose: () => void;
    children: React.ReactNode;
    /** Extra classes on the panel — `option-sheet` caps its height, for one. */
    className?: string;

dtsPropsFor.Modal:
label: string;
    onClose: () => void;
    children: React.ReactNode;
    className?: string;

dtsPropsFor.SheetHead:
title: React.ReactNode;
    /** Sits before the title — a type glyph, usually. */
    icon?: React.ReactNode;
    /** Sits between the title and the close button. */
    children?: React.ReactNode;
    /** Focused on open, so the dialog receives focus without stealing a field. */
    autoFocus?: boolean;

dtsPropsFor.Term:
tip: string;
    children: React.ReactNode;
    chip?: boolean;
    /** -1 takes it out of the tab order, for a Term inside a roving composite. */
    tabIndex?: number;
